def invoice_matches(amounts, target, k):
    vals = sorted(amounts)
    out, pick = [], []

    def walk(start, left):
        if left == 0:
            out.append(pick[:])
            return
        if len(pick) == k:
            return
        for i in range(start, len(vals)):
            if vals[i] > left:
                break
            if i > start and vals[i] == vals[i - 1]:
                continue
            pick.append(vals[i])
            walk(i + 1, left - vals[i])
            pick.pop()

    walk(0, target)
    return out

